/**
* Compute kernel between feature vector and support vector.
* Kernel type: rbf
*/
float compute_kernel(float *x, ...) {
    va_list w;
    va_start(w, 14);
    float kernel = 0.0;

    for (uint16_t i = 0; i < 14; i++) {
        kernel += pow(x[i] - va_arg(w, double), 2);
    }

    return exp(-0.1 * kernel);
}